   "# Algebraic Datatypes (ADTs) a.k.a. (Recursive) Sum Types #\n\n# The type Response can be constructed using one of three constructors #\ntype Response = \n+ Approved\n+ Declined(reason=String)\n+ Pending in \n\n# The constructors are introduced alongside type definitions as values #\nlet r1 = Approved in # r1 : Response #\n\n# If the constructor has an argument, it has a function type #\nlet r2 = Declined(\"no permission\") in \n\n# The expected type can be used to disambiguate shadowed constructors #\ntype Response' = \n+ Approved\n+ Declined in \nlet r3 = Declined(\"does not work\") in \nlet r3 : Response = Declined(\"works\") in \n\n# Pattern matching with case follows the same basic logic #\n# Patterns are considered in top-down order #\nlet not_finally_declined(r : Response) = \ncase r\n| Approved => true\n| Declined(reason) => \nif reason == \"resubmit\" then true \nelse false\n| Pending => true\nend in \n\n# The coverage checker warns about exhaustiveness and redundany issues #\n# (holes in patterns are handled as described in Yuan et al, OOPSLA 2023) #\nlet declined(r: Response) = \ncase r\n| Approved => false\n| Declined(_) => true\n| Approved => false\nend in \n\n# Type equivalence is structural in Hazel #\n# constructor order does not matter #\ntype Response2 = \n+ Approved\n+ Pending\n+ Declined(reason=String) in \nlet x : Response = Pending in \nlet y : Response2 = x in # no error, Response == Response2 #\n\n# Recursive Sum Types #\n# As an example, let's define the lambda calculus #\n\n# An Expression is a variable, function, or application #\n# Notice that the function and application cases are recursive. #\ntype Exp =\n+ Var(String)\n+ Lam(String, Exp)\n+ Ap(Exp, Exp) in\n\n# Recursive types can be written explicitly if you want #\ntype Exp2 = rec Exp -> \n+ Var(String)\n+ Lam(String, Exp) \n+ Ap(Exp, Exp) in \n\nlet e1 : Exp = Var(\"abc\") in \nlet e2 : Exp2 = e1 in # no error, Exp == Exp2 #\n\n# Substitute Exp v for variable name in Exp e #\nlet subst(v: Exp, x: String, e: Exp): Exp =\ncase e\n| Var(y) =>\nif x == y then v else e\n| Lam(y, body) =>\nif x == y then e \nelse Lam(y, subst(v, x, body))\n| Ap(f, arg) =>\nAp(subst(v, x, f), subst(v, x, arg)) \nend in\n\n# Evaluation can result in either an Exp or an Error #\ntype Result =\n+ Error(String)\n+ Ok(Exp)\nin\n\n# Evaluation by substitution #\nlet evaluate(e : Exp): Result =\ncase e\n| Var(x) => Error(\"Free Variable: \" ++ x)\n| Lam(x, body) => Ok(Lam(x, body))\n| Ap(e1, e2) =>\ncase evaluate(e1)\n| Ok(Lam(x, body))=>\ncase evaluate(e2)\n| Error(err) => Error(err)\n| Ok(arg) => evaluate(subst(arg, x, body)) \nend\n| _ => Error(\"Not a Function\") \nend \nend in\n\nlet res1 = evaluate(Var(\"yo\")) in \nlet res2 = evaluate(Ap(Var(\"no\"), Lam(\"bro\", Var(\"bro\")))) in \nlet res3 = evaluate(Lam(\"yo\", Var(\"yo\"))) in \nlet res4 = evaluate(Ap(Lam(\"yo\", Var(\"yo\")), Lam(\"bro\", Var(\"bro\")))) in \n\ntest res1 == Error(\"Free Variable: yo\") end;\ntest res2 == Error(\"Not a Function\") end;\ntest res3 == Ok(Lam(\"yo\", Var(\"yo\"))) end;\ntest res4 == Ok(Lam(\"bro\", Var(\"bro\"))) end;\n\n# Parameterized Types #\n# Types can have parameters, and they have type-level function semantics #\ntype ResultP(err, ok) = \n+ Error(err)\n+ Ok(ok)\nin \ntype Result2 = ResultP(String, Exp) in \nlet res1' : Result2 = res1 in # no error, Result == Result2 #\n\n# You can write these as explicit typfuns if you would like #\ntype ResultP' = typfun err, ok -> \n+ Error(err)\n+ Ok(ok) in \ntype Result3 = ResultP'(String, Exp) in \nlet res1'' : Result3 = res1 in # no error, Result == Result3 #\n\ntype ResultP_curried = typfun err -> typfun ok -> \n+ Error(err)\n+ Ok(ok) in \ntype Result4 = ResultP_curried(String)(Exp) in \nlet res1''' : Result4 = res1 in \n\n# Can have non-uniform recursion #\ntype NUList(a) = \n+ Nil\n+ Cons(a, NUList((Int, a))) in \nlet x : NUList(String) = Cons(\n\"a\", \nCons((1, \"b\"), \nCons(((1, (2, \"c\")), Nil)))) in \n\n# Currently, no higher kinded abstraction. #\n";
